    assert_eq!((moved, team.red, team.blue), (2, 0, 6));
    // Nothing left to move.
    let moved = transfer(&mut team.red, &mut team.blue, 1);
    assert_eq!((moved, team.red, team.blue), (0, 0, 6));

    let mut scores = vec![4, 0, 7];
