/// Swap the first and the last element. A list with fewer than two
/// elements is left as it is.
fn swap_ends(words: &mut Vec<String>) {
    let len = words.len();
    if len >= 2 {
        // `words[0]` and `words[len - 1]` can't both be borrowed mutably at once,
        // and a String can't be moved out of an index. `swap` does both jobs.
        words.swap(0, len - 1);
    }
}

fn main() {
    let mut words = vec![
        String::from("first"),
        String::from("second"),
        String::from("third"),
        String::from("last"),
    ];
    let first_text = words[0].as_ptr();
    let last_text = words[3].as_ptr();

    swap_ends(&mut words);
    assert_eq!(words, ["last", "second", "third", "first"]);
    assert_eq!(
        words[0].as_ptr(),
